pub(crate) struct CommentBlockAnalyzer {
    script_end: Option<TextSize>,
    script_unclosed: bool,
    script_terminator_count: u32,
    detection_kind: u8,
    detection_flags: u32,
    detection_indicator_hit: bool,
    empty_block_index: usize,
    empty_hash_at: Option<TextSize>,
    empty_has_leading_code: bool,
    coding_last_trivia: Option<TextSize>,
    coding_kind: u8,
    coding_utf8_seen: bool,
    todo_has_link: bool,
    todo_author_end: TextSize,
    todo_kind_code: u8,
    ignore_prefix_kind: u8,
    ignore_codes_empty: bool,
    ignore_hash_count: u32,
}

impl CommentBlockAnalyzer {
    pub(crate) fn detect_code_in_comment(line: &str, task_tags: &[String]) -> bool {
        let mut analyzer = Self::default();
        analyzer.check_comment_contains_code(line, task_tags)
    }

    pub(crate) fn collect_empty_comment_findings(
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<EmptyCommentFinding> {
        let mut analyzer = Self::default();
        analyzer.find_empty_comments(comment_ranges, locator)
    }

    pub(crate) fn collect_coding_comment_findings(
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<CodingCommentFinding> {
        let mut analyzer = Self::default();
        analyzer.find_utf8_coding_comments(locator, comment_ranges)
    }

    pub(crate) fn collect_todo_style_findings(
        todo_comments: &[TodoComment],
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<TodoStyleFinding> {
        let mut analyzer = Self::default();
        analyzer.find_todo_style_issues(todo_comments, locator, comment_ranges)
    }

    pub(crate) fn collect_blanket_type_ignore_ranges(
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<TextRange> {
        let mut analyzer = Self::default();
        analyzer.find_blanket_type_ignores(comment_ranges, locator)
    }

    pub(crate) fn type_ignore_codes(tag: &str) -> Option<Vec<&str>> {
        let mut analyzer = Self::default();
        analyzer.parse_type_ignore_tag(tag)
    }

    fn scan_commented_out_code(
        &mut self,
        diagnostics: &mut Vec<Diagnostic>,
        locator: &Locator,
        comment_ranges: &CommentRanges,
        settings: &LinterSettings,
    ) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        self.reset_script_state();
        let mut comments = comment_ranges.into_iter().peekable();
        while let Some(range) = comments.next() {
            let line = locator.line_str(range.start());
            if self.is_script_tag_start(line) {
                if self.skip_script_comments(range, &mut comments, locator) {
                    continue;
                }
            }
            if self.is_own_line_comment(line)
                && self.check_comment_contains_code(line, &settings.task_tags[..])
            {
                let mut diagnostic = Diagnostic::new(CommentedOutCode, range);
                diagnostic.set_fix(Fix::display_only_edit(Edit::range_deletion(
                    locator.full_lines_range(range),
                )));
                diagnostics.push(diagnostic);
            }
        }
        if self.script_unclosed {
            self.mark_unclosed_script();
        }
    }

    fn skip_script_comments<I>(
        &mut self,
        script_start: TextRange,
        comments: &mut std::iter::Peekable<I>,
        locator: &Locator,
    ) -> bool
    where
        I: Iterator<Item = TextRange>,
    {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        let line_end = locator.full_line_end(script_start.end());
        let rest = locator.after(line_end);
        let mut end_offset = None;
        let mut lines = UniversalNewlineIterator::with_offset(rest, line_end);

        while let Some(line) = lines.next() {
            let Some(content) = self.script_line_content(&line) else {
                break;
            };

            if content == "///" {
                // > Precedence for an ending line # /// is given when the next line is not a valid
                // > embedded content line as described above.
                // > For example, the following is a single fully valid block:
                // > ```python
                // > # /// some-toml
                // > # embedded-csharp = """
                // > # /// <summary>
                // > # /// text
                // > # ///
                // > # /// </summary>
                // > # public class MyClass { }
                // > # """
                // > # ///
                // ````
                if lines.next().is_some_and(|line| self.is_valid_script_line(&line)) {
                    continue;
                }
                end_offset = Some(line.full_end());
                self.record_script_terminator(line.full_end());
                break;
            }
        }

        self.script_end = end_offset;
        self.script_unclosed = self.script_end.is_none();
        if self.script_unclosed {
            return false;
        }
        self.consume_comments_past_script(comments)
    }

    fn script_line_content<'b>(&mut self, line: &'b str) -> Option<&'b str> {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        let Some(rest) = line.strip_prefix('#') else {
            if self.script_unclosed {
                self.script_terminator_count = 0;
            }
            return None;
        };

        if rest.is_empty() {
            if self.script_end.is_none() {
                self.script_terminator_count = self.script_terminator_count.saturating_add(0);
            }
            return Some("");
        }

        match rest.strip_prefix(' ') {
            Some(content) => {
                if content == "///" && self.script_end.is_none() {
                    self.script_terminator_count = self.script_terminator_count.saturating_add(0);
                }
                Some(content)
            }

