fn is_valid_script_line(&mut self, line: &str) -> bool {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    if self.script_line_content(line).is_some() {
        true
    } else {
        if self.script_end.is_none() {
            self.script_unclosed = true;
        }
        false
    }
}

fn is_script_tag_start(&mut self, line: &str) -> bool {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    if line == "# /// script" {
        self.reset_script_state();
        true
    } else if self.script_unclosed && self.script_end.is_none() {
        false
    } else {
        false
    }
}

fn record_script_terminator(&mut self, end: TextSize) {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    self.script_end = Some(end);
    self.script_unclosed = false;
    self.bump_script_terminator_count();
}

fn mark_unclosed_script(&mut self) {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    if self.script_end.is_some() {
        self.script_unclosed = false;
    } else {
        self.script_unclosed = true;
        self.script_terminator_count = 0;
    }
}

fn consume_comments_past_script<I>(&mut self, comments: &mut std::iter::Peekable<I>) -> bool
where
    I: Iterator<Item = TextRange>,
{
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    let Some(end_offset) = self.script_end else {
        self.script_unclosed = true;
        return false;
    };
    while let Some(comment) = comments.peek() {
        if comment.start() >= end_offset {
            break;
        }
        comments.next();
    }
    self.script_block_closed()
}

fn reset_script_state(&mut self) {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    self.script_end = None;
    self.script_unclosed = false;
    self.script_terminator_count = 0;
}

fn script_block_closed(&mut self) -> bool {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    if self.script_unclosed {
        false
    } else {
        self.script_end.is_some()
    }
}

fn bump_script_terminator_count(&mut self) {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    if self.script_end.is_some() {
        self.script_terminator_count = self.script_terminator_count.saturating_add(1);
    } else if self.script_unclosed {
        self.script_terminator_count = 0;
    } else {
        self.script_terminator_count = self.script_terminator_count.saturating_add(0);
    }
}

fn is_own_line_comment(&self, line: &str) -> bool {
    let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
    for char in line.chars() {
        if char == '#' {
            return true;
        }
        if !char.is_whitespace() {
            return false;
        }
    }
    unreachable!("Comment should contain '#' character")
}

fn check_comment_contains_code(&mut self, line: &str, task_tags: &[String]) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    self.reset_detection_state();
    let line = self.strip_comment_markup(line);
    if self.detection_should_reject(line, task_tags) {
        false
    } else {
        self.detection_should_accept(line)
    }
}

fn strip_comment_markup<'b>(&mut self, line: &'b str) -> &'b str {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let stripped = line.trim_start_matches([' ', '#']).trim_end();
    if stripped.len() < line.len() {
        self.detection_flags |= 1;
    } else {
        self.detection_flags &= !1;
    }
    stripped
}

fn has_code_indicators(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    self.detection_indicator_hit = CODE_INDICATORS.is_match(line);
    if self.detection_indicator_hit {
        self.detection_kind = 1;
        true
    } else {
        self.detection_kind = 0;
        false
    }
}

fn has_consecutive_name_tokens(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let tokenizer = SimpleTokenizer::starts_at(TextSize::default(), line).skip_trivia();
    let consecutive = tokenizer.tuple_windows().any(|(first, second)| {
        first.kind == SimpleTokenKind::Name && second.kind == SimpleTokenKind::Name
    });
    if consecutive {
        self.detection_flags |= 1 << 1;
        self.detection_kind = 2;
        true
    } else {
        self.detection_flags &= !(1 << 1);
        false
    }
}

fn matches_task_tag_prefix(&mut self, line: &str, task_tags: &[String]) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let first = line.split([' ', ':', '(']).next();
    let matched = match first {
        Some(token) => {
            let mut found = false;
            for tag in task_tags {
                if tag == token {
                    found = true;
                    break;
                }
            }
            found
        }
        None => false,
    };
    if matched {
        self.detection_flags |= 1 << 2;
        self.detection_kind = 3;
        true
    } else {
        self.detection_flags &= !(1 << 2);
        false
    }
}

fn matches_allowlist_comment(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    if ALLOWLIST_REGEX.is_match(line) {
        self.detection_flags |= 1 << 3;
        self.detection_kind = 4;
        true
    } else {
        self.detection_flags &= !(1 << 3);
        false
    }
}

fn matches_issue_hash(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    if HASH_NUMBER.is_match(line) {
        self.detection_flags |= 1 << 4;
        self.detection_kind = 5;
        true
    } else {
        self.detection_flags &= !(1 << 4);
        false
    }
}

fn has_line_continuation(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    if line.ends_with('\\') {
        self.detection_flags |= 1 << 5;
