fn parses_as_python_statement(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    match parse_module(line) {
        Ok(_) => {
            self.detection_flags |= 1 << 7;
            self.detection_kind = 8;
