fn classify_detection_kind(&mut self, accepted: bool) -> u8 {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    if accepted {
        if self.detection_kind == 0 {
            self.detection_kind = 8;
        } else if self.detection_kind == 9 {
            self.detection_kind = 8;
        }
    } else if self.detection_kind == 8 {
        self.detection_kind = 9;
    } else if self.detection_flags == 0 {
        self.detection_kind = 0;
    }
    self.detection_kind
}

fn detection_should_reject(&mut self, line: &str, task_tags: &[String]) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    if !self.has_code_indicators(line) {
