fn strip_comment_markup<'b>(&mut self, line: &'b str) -> &'b str {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let stripped = line.trim_start_matches([' ', '#']).trim_end();
    if stripped.len() < line.len() {
        self.detection_flags |= 1;
    } else {
        self.detection_flags &= !1;
    }
    stripped
}

fn has_code_indicators(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    self.detection_indicator_hit = CODE_INDICATORS.is_match(line);
    if self.detection_indicator_hit {
