        true
    } else {
        self.detection_kind = 0;
        false
    }
}

fn has_consecutive_name_tokens(&mut self, line: &str) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let tokenizer = SimpleTokenizer::starts_at(TextSize::default(), line).skip_trivia();
    let consecutive = tokenizer.tuple_windows().any(|(first, second)| {
        first.kind == SimpleTokenKind::Name && second.kind == SimpleTokenKind::Name
    });
    if consecutive {
        self.detection_flags |= 1 << 1;
        self.detection_kind = 2;
        true
    } else {
        self.detection_flags &= !(1 << 1);
        false
    }
}

fn matches_task_tag_prefix(&mut self, line: &str, task_tags: &[String]) -> bool {
    let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
    let first = line.split([' ', ':', '(']).next();
