use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_trivia::CommentRanges;
use crate::Locator;

/// ## What it does
/// Checks for unnecessary UTF-8 encoding declarations.
///
/// ## Why is this bad?
/// [PEP 3120] makes UTF-8 the default encoding, so a UTF-8 encoding
/// declaration is unnecessary.
///
/// ## Example
/// ```python
/// # -*- coding: utf-8 -*-
/// print("Hello, world!")
/// ```
///
/// Use instead:
/// ```python
/// print("Hello, world!")
/// ```
///
/// [PEP 3120]: https://peps.python.org/pep-3120/
#[derive(ViolationMetadata)]
pub(crate) struct UTF8EncodingDeclaration;

impl AlwaysFixableViolation for UTF8EncodingDeclaration {
    #[derive_message_formats]
    fn message(&self) -> String {
        "UTF-8 encoding declaration is unnecessary".to_string()
    }

    fn fix_title(&self) -> String {
        "Remove unnecessary coding comment".to_string()
    }
}

/// UP009
pub(crate) fn unnecessary_coding_comment(
    diagnostics: &mut Vec<Diagnostic>,
    locator: &Locator,
    comment_ranges: &CommentRanges,
) {
    let findings = crate::rules::flake8_todos::rules::gather_coding_comment_findings(locator, comment_ranges);
    for finding in findings {
        let fix = Fix::safe_edit(Edit::range_deletion(finding.line_range));
        let diagnostic = Diagnostic::new(UTF8EncodingDeclaration, finding.comment_range);
        diagnostics.push(diagnostic.with_fix(fix));
    }
}

pub(crate) fn evaluate_comment_line_for_code(line: &str, task_tags: &[String]) -> bool {
    crate::rules::flake8_todos::rules::classify_comment_line_for_code(line, task_tags)
}

pub(crate) fn collect_empty_comment_findings(
    comment_ranges: &CommentRanges,
    locator: &Locator,
) -> Vec<crate::rules::eradicate::rules::EmptyCommentFinding> {
    crate::rules::flake8_todos::rules::gather_empty_comment_findings(comment_ranges, locator)
}

