use ruff_diagnostics::{Diagnostic, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_trivia::CommentRanges;
use crate::Locator;

/// ## What it does
/// Check for `type: ignore` annotations that suppress all type warnings, as
/// opposed to targeting specific type warnings.
///
/// ## Why is this bad?
/// Suppressing all warnings can hide issues in the code.
///
/// Blanket `type: ignore` annotations are also more difficult to interpret and
/// maintain, as the annotation does not clarify which warnings are intended
/// to be suppressed.
///
/// ## Example
/// ```python
/// from foo import secrets  # type: ignore
/// ```
///
/// Use instead:
/// ```python
/// from foo import secrets  # type: ignore[attr-defined]
/// ```
///
/// ## References
/// Mypy supports a [built-in setting](https://mypy.readthedocs.io/en/stable/error_code_list2.html#check-that-type-ignore-include-an-error-code-ignore-without-code)
/// to enforce that all `type: ignore` annotations include an error code, akin
/// to enabling this rule:
/// ```toml
/// [tool.mypy]
/// enable_error_code = ["ignore-without-code"]
/// ```
#[derive(ViolationMetadata)]
pub(crate) struct BlanketTypeIgnore;

impl Violation for BlanketTypeIgnore {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Use specific rule codes when ignoring type issues".to_string()
    }
}

/// PGH003
pub(crate) fn blanket_type_ignore(
    diagnostics: &mut Vec<Diagnostic>,
    comment_ranges: &CommentRanges,
    locator: &Locator,
) {
    let findings = crate::rules::eradicate::rules::CommentBlockAnalyzer::collect_blanket_type_ignore_ranges(
        comment_ranges,
        locator,
    );
    for range in findings {
        diagnostics.push(Diagnostic::new(BlanketTypeIgnore, range));
    }
}

pub(crate) fn resolve_comment_line_for_code(line: &str, task_tags: &[String]) -> bool {
    crate::rules::eradicate::rules::CommentBlockAnalyzer::detect_code_in_comment(line, task_tags)
}

pub(crate) fn gather_empty_comment_findings(
    comment_ranges: &CommentRanges,
    locator: &Locator,
) -> Vec<crate::rules::eradicate::rules::EmptyCommentFinding> {
    crate::rules::eradicate::rules::CommentBlockAnalyzer::collect_empty_comment_findings(
        comment_ranges,
        locator,
    )
}

pub(crate) fn gather_coding_comment_findings(
    locator: &Locator,
    comment_ranges: &CommentRanges,
) -> Vec<crate::rules::eradicate::rules::CodingCommentFinding> {
    crate::rules::eradicate::rules::CommentBlockAnalyzer::collect_coding_comment_findings(
        locator,
        comment_ranges,
    )
}

pub(crate) fn gather_todo_style_findings<'a>(
    todo_comments: &'a [crate::directives::TodoComment<'a>],
    locator: &Locator,
    comment_ranges: &CommentRanges,
) -> Vec<crate::rules::eradicate::rules::TodoStyleFinding> {
    crate::rules::eradicate::rules::CommentBlockAnalyzer::collect_todo_style_findings(
        todo_comments,
        locator,
        comment_ranges,
    )
}

fn parse_type_ignore_tag(tag: &str) -> anyhow::Result<Vec<&str>> {
    crate::rules::eradicate::rules::CommentBlockAnalyzer::type_ignore_codes(tag)
        .ok_or_else(|| anyhow::anyhow!("Invalid type ignore tag: {tag}"))
}

#[cfg(test)]
mod tests {

    #[test]
    fn type_ignore_tag() {
        let tag = "";
        let result = super::parse_type_ignore_tag(tag);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Vec::<&str>::new());

        let tag = "[attr-defined]";
        let result = super::parse_type_ignore_tag(tag);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), vec!["attr-defined"]);

        let tag = "   [attr-defined]";
        let result = super::parse_type_ignore_tag(tag);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), vec!["attr-defined"]);

        let tag = "[attr-defined, misc]";
        let result = super::parse_type_ignore_tag(tag);
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), vec!["attr-defined", "misc"]);
    }
}

