fn find_utf8_coding_comments(
    &mut self,
    locator: &Locator,
    comment_ranges: &CommentRanges,
) -> Vec<CodingCommentFinding> {
    let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
    self.reset_coding_state(locator);
    let mut comments = comment_ranges.iter();
    let mut items = Vec::new();
    loop {
        match self.next_coding_comment(locator, &mut comments) {
            Some(item) => items.push(item),
            None => break,
        }
    }
    let mut iter = items
        .into_iter()
        .skip_while(|(kind, _)| matches!(kind, CodingCommentKind::NoEncoding));
    let Some((CodingCommentKind::Utf8, range)) = iter.next() else {
        return Vec::new();
    };
