    let second = iter.next().map(|(kind, _)| kind);
    if self.later_encoding_conflicts(first, second) {
        return Vec::new();
    }
    vec![range]
}

fn reset_coding_state(&mut self, locator: &Locator) {
    let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
    self.coding_last_trivia = Some(locator.bom_start_offset());
    self.coding_kind = 0;
    self.coding_utf8_seen = false;
}

fn next_coding_comment(
    &mut self,
    locator: &Locator,
    comments: &mut std::slice::Iter<'_, TextRange>,
) -> Option<(CodingCommentKind, CodingCommentFinding)> {
    let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
    let comment = comments.next()?;
    let line_range = locator.full_line_range(comment.start());
    if !self.trivia_before_comment_is_blank(locator, comment.start()) {
        return None;
    }
    self.coding_last_trivia = Some(comment.end());
    let finding = CodingCommentFinding {
        comment_range: comment.range(),
        line_range,
    };
    let kind = self.classify_coding_line(locator, line_range);
    Some((kind, finding))
}

fn classify_coding_line(&mut self, locator: &Locator, line_range: TextRange) -> CodingCommentKind {
    let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
    match CODING_COMMENT_REGEX.captures(locator.slice(line_range)) {
        Some(captures) => {
